TEAMS_WEBHOOK_URL = os.environ.get('TEAMS_WEBHOOK_URL', '')

def teams_notification_callback(context):
    if os.environ.get('ENABLE_EXTERNAL_NOTIFICATIONS') != 'true':
        return
    dag_run = context['dag_run']
    ti = context['ti']
    timezone = pytz.timezone('America/Sao_Paulo')
    dag_status = 'success'
    for task in dag_run.get_task_instances():
        if task.state == State.FAILED:
            dag_status = 'failed'
            break
    start = dag_run.start_date
    if start:
        start = start.astimezone(timezone)
        start_str = start.strftime('%d/%m/%Y %H:%M')
    else:
        start_str = 'N/A'
    end = datetime.utcnow().replace(tzinfo=pytz.utc).astimezone(timezone)
    end_str = end.strftime('%d/%m/%Y %H:%M')
    if start:
        duration_seconds = (end - start).total_seconds()
        minutes = int(duration_seconds // 60)
        seconds = int(duration_seconds % 60)
        duration_str = f'{minutes:02d}:{seconds:02d} minutos'
    else:
        duration_str = 'N/A'
    dag_link = f'https://airflow.example.com{ti.dag_id}/grid'
    status_emoji = '✅' if dag_status == 'success' else '❌'
    status_text = 'SUCESSO' if dag_status == 'success' else 'FALHA'
    payload = {'@type': 'MessageCard', '@context': 'https://schema.org/extensions', 'summary': f'Airflow DAG {ti.dag_id} - {status_text}', 'themeColor': '0076D7' if dag_status == 'success' else 'FF0000', 'title': f'demo_mysql_nps_merge - STATUS {status_emoji}', 'sections': [{'facts': [{'name': 'DAG', 'value': ti.dag_id}, {'name': 'Status', 'value': status_text}, {'name': 'Início', 'value': start_str}, {'name': 'Fim', 'value': end_str}, {'name': 'Duração', 'value': duration_str}, {'name': 'Run ID', 'value': dag_run.run_id}], 'markdown': True}], 'potentialAction': [{'@type': 'OpenUri', 'name': '🔗 Ver DAG no Airflow', 'targets': [{'os': 'default', 'uri': dag_link}]}]}
    response = requests.post(TEAMS_WEBHOOK_URL, json=payload)
    if response.status_code != 200:
        raise Exception(f'Erro ao enviar notificação para Teams: {response.text}')
default_args = {'owner': 'aloisio lemos', 'retries': 1, 'retry_delay': timedelta(minutes=5)}
gcp_bucket_airflow = 'demo-airflow-data-bucket'
